create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', avatar_url text, department text, academic_year text, bio text check (char_length(bio)<=280), role text not null default 'user' check(role in ('user','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lost_found_items (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, listing_type text not null check(listing_type in ('lost','found')), item_name text not null check(char_length(item_name) between 3 and 120), category text not null, description text not null check(char_length(description)<=2000), location text not null, event_date date not null, image_urls text[] not null default '{}', status text not null default 'active' check(status in ('active','potential_match','claimed','recovered','returned','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lending_items (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, title text not null, category text not null, description text not null, pickup_location text not null, condition text not null default 'good', max_borrow_days integer not null default 7 check(max_borrow_days between 1 and 30), image_urls text[] not null default '{}', status text not null default 'available' check(status in ('available','requested','reserved','borrowed','return_pending','unavailable','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.borrow_requests (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.lending_items(id) on delete cascade, borrower_id uuid not null references public.profiles(id) on delete cascade, start_date date not null, return_date date not null, message text check(char_length(message)<=1000), status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled','expired','completed')), created_at timestamptz not null default now(), check(return_date>start_date), unique(item_id,borrower_id,status));
create table public.borrow_transactions (id uuid primary key default gen_random_uuid(), request_id uuid unique not null references public.borrow_requests(id), item_id uuid not null references public.lending_items(id), lender_id uuid not null references public.profiles(id), borrower_id uuid not null references public.profiles(id), start_date date not null, due_date date not null, actual_return_date timestamptz, status text not null default 'scheduled' check(status in ('scheduled','active','return_requested','returned','cancelled')), created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, message text not null, entity_id uuid, entity_type text, read boolean not null default false, created_at timestamptz not null default now());
create table public.blocked_users (blocker_id uuid references public.profiles(id) on delete cascade, blocked_id uuid references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(blocker_id,blocked_id), check(blocker_id<>blocked_id));
alter table public.profiles enable row level security; alter table public.lost_found_items enable row level security; alter table public.lending_items enable row level security; alter table public.borrow_requests enable row level security; alter table public.borrow_transactions enable row level security; alter table public.notifications enable row level security; alter table public.blocked_users enable row level security;
create policy "profiles readable" on public.profiles for select using(true); create policy "own profile update" on public.profiles for update using(auth.uid()=id);
create policy "active lf readable" on public.lost_found_items for select using(status in ('active','potential_match') or owner_id=auth.uid()); create policy "own lf insert" on public.lost_found_items for insert with check(owner_id=auth.uid()); create policy "own lf modify" on public.lost_found_items for all using(owner_id=auth.uid());
create policy "lend readable" on public.lending_items for select using(status='available' or owner_id=auth.uid()); create policy "own lend insert" on public.lending_items for insert with check(owner_id=auth.uid()); create policy "own lend modify" on public.lending_items for all using(owner_id=auth.uid());
create policy "request party read" on public.borrow_requests for select using(borrower_id=auth.uid() or exists(select 1 from public.lending_items i where i.id=item_id and i.owner_id=auth.uid())); create policy "request borrower insert" on public.borrow_requests for insert with check(borrower_id=auth.uid()); create policy "notification owner" on public.notifications for all using(recipient_id=auth.uid()); create policy "block owner" on public.blocked_users for all using(blocker_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create index lf_search_idx on public.lost_found_items(listing_type,category,created_at desc); create index lending_search_idx on public.lending_items(status,category,created_at desc); create index notifications_recipient_idx on public.notifications(recipient_id,read,created_at desc);
